function openSearch() {
  $("#search").classList.add("open");
  $("#search-close").textContent = LANG === "en" ? "Close ✕" : "닫기 ✕";
  const i = $("#search-form").q;
  i.placeholder = t("search");
  $("#search-hint").textContent = t("searchHint");
  setTimeout(() => i.focus(), 30);
}
function closeSearch() {
  $("#search").classList.remove("open");
}
$("#open-search").onclick = openSearch;
$("#search-form").onsubmit = (e) => {
  e.preventDefault();
  closeSearch();
  goto("#/books?q=" + encodeURIComponent(e.target.q.value));
};
addEventListener("keydown", (e) => {
  if (e.key === "Escape") closeSearch();
  if (e.key === "/" && !/input|textarea/i.test(document.activeElement.tagName)) {
    e.preventDefault();
    openSearch();
  }
});
const NAV = ["books", "series", "authors", "world", "about", "contact"];
let io;
const PATHMODE = typeof window.__BASE === "string";
function goto(h) {
  if (PATHMODE) {
    history.pushState(null, "", window.__BASE + h.slice(1));
    vtNav(() => {
      route();
      window.scrollTo(0, 0);
    });
  } else location.hash = h;
}
function route() {
  const h = location.hash.slice(1) || (PATHMODE ? (location.pathname.slice(window.__BASE.length).replace(/\/+$/, "") || "/") + location.search : "") || "/";
  const [path, qs] = h.split("?");
  const params = new URLSearchParams(qs || "");
  const parts = path.split("/").filter(Boolean).map(decodeURIComponent);
  let k = parts[0] || "";
  document.documentElement.lang = LANG;
  $("#nav").innerHTML = NAV.map((n) => `<a href="#/${n}" class="${k === n || k === "book" && n === "books" || k === "author" && n === "authors" || (k === "submit" || k === "permissions" || k === "careers" || k === "for-authors" || k === "press") && n === "contact" || k === "imprint" && n === "about" ? "on" : ""}">${t(n)}</a>`).join("");
  document.querySelectorAll(".lang button").forEach((b) => b.classList.toggle("on", b.dataset.l === LANG));
  const pages = {
    "": home,
    books: () => booksPage(params),
    book: () => book(parts[1]),
    series: () => seriesPage(parts[1]),
    authors: authorsPage,
    author: () => authorPage(parts[1]),
    world: () => worldPage(params),
    about,
    contact,
    press: pressPage,
    imprint: () => imprintPage(parts[1]),
    "for-authors": forAuthorsPage,
    submit: submitPage,
    permissions: permissionsPage,
    careers: careersPage
  };
  if (!Object.hasOwn(pages, k)) k = "\0";
  $("#app").innerHTML = (pages[k] || notFound)();
  {
    const base = LANG === "en" ? "THE BOOKMAN · The Book Man" : "THE BOOKMAN · 책 읽어주는 남자", h1 = document.querySelector("#app h1");
    const h1t = h1 && ((c) => {
      c.querySelectorAll("br").forEach((x) => x.replaceWith(" "));
      return c.textContent.replace(/\s+/g, " ").trim();
    })(h1.cloneNode(true));
    document.title = !k ? base : !pages[k] ? (LANG === "en" ? "Page not found" : "찾는 페이지가 없습니다") + " — THE BOOKMAN" : (k === "book" && byIsbn[parts[1]] ? title(byIsbn[parts[1]]) : h1t || (T[LANG][k] || "")) + " — THE BOOKMAN";
  }
  $("#ft").innerHTML = footer();
  $("#hdr").classList.remove("open");
  clearInterval(window.__auRoll);
  if (k === "" || k === "world" || k === "about") countUp();
  if (k === "") revealLines();
  if (k === "about") aboutReveal();
  sentenceBreaks();
  if (k === "book") {
    tiltCover();
    if (parts[1]) vtFrom = parts[1];
  }
  if (!k) {
    renderWorld(6);
    renderPicks();
    rotateAuthors();
  }
  if (k === "world") renderWorld(0);
  if (k === "authors") wireAuthors();
  if (k === "books") wireTools(params, "#/books");
  if (k === "world") wireTools(params, "#/world");
  if (io) io.disconnect();
  io = new IntersectionObserver((es) => es.forEach((e) => {
    if (e.isIntersecting) {
      e.target.classList.add("in");
      io.unobserve(e.target);
    }
  }), { rootMargin: "0px 0px -10% 0px" });
  document.querySelectorAll(".fade").forEach((el) => io.observe(el));
}
document.querySelectorAll(".lang button").forEach((b) => b.addEventListener("click", () => {
  LANG = b.dataset.l;
  try {
    localStorage.setItem("tbm-lang", LANG);
  } catch (e) {
  }
  route();
}));
addEventListener("hashchange", () => vtNav(() => {
  route();
  window.scrollTo(0, 0);
}));
if (PATHMODE) {
  addEventListener("popstate", () => vtNav(route));
  document.addEventListener("click", (e) => {
    const a = e.target.closest && e.target.closest("a");
    if (!a || e.metaKey || e.ctrlKey || e.shiftKey || a.target === "_blank") return;
    const href = a.getAttribute("href") || "";
    if (!href.startsWith("#/")) return;
    e.preventDefault();
    goto(href);
  });
}
